import { mkdtemp, mkdir, readFile, writeFile, symlink, chmod, readdir, unlink } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import { join } from 'node:path';
import { prepareNativeEnvironment } from 'file:///home/genie/orca/workspaces/genie/mikro-engine-split/.genie/wishes/mikro-engine-split/experiments/native-workflow-observer.mjs';
import { reconcileSessions } from 'file:///home/genie/orca/workspaces/genie/mikro-engine-split/.genie/wishes/mikro-engine-split/experiments/native-session-accounting.mjs';
const base = '/home/genie/.local/share/mikro-engine-split/experiments-g8';
const proofRoot = await mkdtemp(join(base, 'contained-native-proof-'));
const prepared = JSON.parse(await readFile(join(base, 'prepared-native-contained-workflow.json'), 'utf8')).workflow.smoke;
const cell = { ...prepared, runRoot: proofRoot };
const env = await prepareNativeEnvironment(cell);
const external = join(proofRoot, 'external');
await mkdir(external, { mode: 0o700 });
await writeFile(join(external, 'sentinel'), 'UNCHANGED');
const negatives = [];
for (const kind of ['root-symlink', 'home-symlink', 'tmp-symlink', 'root-file', 'nonprivate-root', 'cwd-alias', 'HOME-override', 'GENIE_HOME-override', 'TMPDIR-override', 'DSH_HOME-override', 'XDG_CONFIG_HOME-override', 'XDG_CACHE_HOME-override']) {
  const cwd = join(proofRoot, kind); await mkdir(cwd, { mode: 0o700 });
  const candidate = { ...cell, cwd, launch: { ...cell.launch, env: { ...cell.launch.env } } };
  const runtime = join(cwd, '.g8-runtime');
  if (kind === 'root-symlink') await symlink(external, runtime);
  if (kind === 'root-file') await writeFile(runtime, 'not a directory');
  if (kind === 'nonprivate-root') { await mkdir(runtime, { mode: 0o700 }); await chmod(runtime, 0o755); }
  if (kind === 'home-symlink' || kind === 'tmp-symlink') { await mkdir(runtime, { mode: 0o700 }); await symlink(external, join(runtime, kind.startsWith('home') ? 'home' : 'tmp')); }
  if (kind === 'cwd-alias') { candidate.cwd = join(proofRoot, 'cwd-alias-link'); await symlink(cwd, candidate.cwd); }
  if (kind.endsWith('-override')) candidate.launch.env[kind.slice(0, -9)] = external;
  try { await prepareNativeEnvironment(candidate); throw new Error(`unexpectedly accepted ${kind}`); }
  catch (error) { if (error.message.startsWith('unexpectedly accepted')) throw error; negatives.push({ kind, rejected: true, message: error.message }); }
}
if ((await readdir(external)).join(',') !== 'sentinel' || await readFile(join(external, 'sentinel'), 'utf8') !== 'UNCHANGED') throw new Error('negative fixture followed/wrote outside target');
await mkdir(env.DSH_HOME, { mode: 0o700 });
for (const key of Object.keys(process.env)) delete process.env[key];
Object.assign(process.env, env); process.chdir(cell.cwd);
const require = createRequire('/home/genie/.dsh/runtime/0.2.0-rc.1/node_modules/@deepseek-ai/dsh/package.json');
const load = specifier => import(pathToFileURL(require.resolve(specifier)).href);
const { initializeProfileFromDefault, runProfile } = await load('@deepseek-ai/dsh/profile-boot');
const { createLaunchEnvironmentSnapshot } = await load('@deepseek-ai/dsh-launch-environment');
const { installModelSelection } = await load('@deepseek-ai/dsh-agent');
const { deriveTurnTokenUsage } = await load('@deepseek-ai/dsh-token-meter/client');
const profile = 'contained-filesystem-proof'; initializeProfileFromDefault(profile, 'headless', env.DSH_HOME);
const patch = [
  { id: 'headless-runner', disabled: true }, { id: 'headless-startup', disabled: true }, { id: 'session-title-llm', disabled: true },
  { id: 'agent-default-model', config: { provider: 'deepseek-official', model: 'deepseek-flash' } },
  { id: 'tools', config: { mode: 'native' } },
  { id: 'session-persistence-jsonl', config: { root: join(proofRoot, 'sessions'), compression: 'none' } },
  { id: 'credentials', config: { path: join(env.DSH_HOME, '.credentials.yaml'), dshHome: env.DSH_HOME, watch: false } },
  { id: 'llm-deepseek', config: { apiKeyEnv: 'DEEPSEEK_API_KEY' } },
];
const patchPath = join(proofRoot, 'proof.patch.yml'); await writeFile(patchPath, JSON.stringify(patch), { flag: 'wx', mode: 0o600 });
let boot; let handle; let requestCount = 0;
const proof = { schemaVersion: 1, kind: 'actual-public-sdk-contained-native-filesystem-proof', proofRoot, credentialsProvided: false, nativeWorkflowLaunched: false, negatives, environment: { HOME: env.HOME, GENIE_HOME: env.GENIE_HOME, TMPDIR: env.TMPDIR, DSH_HOME: env.DSH_HOME, XDG_CONFIG_HOME: env.XDG_CONFIG_HOME, XDG_CACHE_HOME: env.XDG_CACHE_HOME } };
try {
  boot = await runProfile({ environment: createLaunchEnvironmentSnapshot([{ source: 'process', values: env }]), profile, patchFiles: [patchPath], args: [] });
  boot.ctx.on('agent/request', () => { requestCount++; throw new Error('no-inference filesystem proof forbids model requests'); });
  handle = await boot.ctx.agents.create({ sessionId: randomUUID(), meta: { cwd: cell.cwd, delegationDepth: 0 }, agentOptions: { provider: 'deepseek-official', model: 'deepseek-flash' }, signal: new AbortController().signal, setup(agentCtx) { installModelSelection(agentCtx, { current: { provider: 'deepseek-official', model: 'deepseek-flash' }, assembled: undefined }); } });
  await handle.agent.whenIdle();
  proof.policy = boot.ctx.sandboxPolicy.resolve({ session: handle.agent.session });
  if (proof.policy.mode !== 'workspace-write' || proof.policy.workspaceRoot !== cell.cwd) throw new Error('native sandbox boundary changed');
  const marker = randomUUID();
  const paths = [join(env.HOME, `fs-proof-${marker}`), join(env.GENIE_HOME, `fs-proof-${marker}`), join(env.TMPDIR, `fs-proof-${marker}`), join(cell.cwd, '.g8-runtime/caller/.mikro/runs', `fs-proof-${marker}`), join(cell.cwd, '.g8-runtime/sdk-receipts', `fs-proof-${marker}`)];
  const forbidden = join(external, `must-not-exist-${marker}`);
  const body = `const fs=require('node:fs');const path=require('node:path');const files=${JSON.stringify(paths)};for(const file of files){fs.mkdirSync(path.dirname(file),{recursive:true,mode:448});fs.writeFileSync(file,'SANDBOX-WRITE-PROVEN');}let deniedCode=null;try{fs.writeFileSync(${JSON.stringify(forbidden)},'FORBIDDEN');}catch(error){deniedCode=error.code;}if(!['EROFS','EACCES','EPERM'].includes(deniedCode))throw Error('external sandbox write was not denied');console.log(JSON.stringify({containedWrites:files,externalWriteDenied:true,deniedCode,home:process.env.HOME,tmpdir:process.env.TMPDIR}));`;
  const quote = value => `'${value.replaceAll("'", "'\\''")}'`;
  proof.toolCommand = `${quote('/home/genie/.hermes/node/bin/node')} -e ${quote(body)}`;
  proof.toolResult = await boot.ctx.tools.execute({ callId: randomUUID(), name: 'bash', arguments: { command: proof.toolCommand, description: 'Verify native operational directories under unchanged sandbox without inference', timeoutMs: 15000 }, agent: handle.agent, signal: new AbortController().signal });
  for (const file of paths) { if (await readFile(file, 'utf8') !== 'SANDBOX-WRITE-PROVEN') throw new Error(`native write failed ${file}`); await unlink(file); }
  try { await readFile(forbidden); throw new Error('external write escaped sandbox'); } catch (error) { if (error.code !== 'ENOENT') throw error; }
  proof.reconciliation = await reconcileSessions(boot.ctx, [handle.agent.session.id], deriveTurnTokenUsage);
  if (proof.reconciliation.blockers.length || proof.reconciliation.sessions.some(session => session.blockers.length)) throw new Error('exact root reconciliation failed');
  proof.success = requestCount === 0;
} catch (error) { proof.failure = { name: error.name, message: error.message, code: error.code ?? null }; proof.success = false; }
finally {
  proof.requestCount = requestCount;
  await handle?.dispose();
  await writeFile(join(proofRoot, 'proof.json'), `${JSON.stringify(proof, null, 2)}\n`, { flag: 'wx', mode: 0o600 });
  console.log(JSON.stringify({ proofPath: join(proofRoot, 'proof.json'), success: proof.success, requestCount, failure: proof.failure ?? null, policy: proof.policy }));
  await boot?.shutdown.shutdown(proof.success ? 0 : 2);
}
if (!proof.success) process.exitCode = 2;
